            while q:
                y,x=q.pop(); pts.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and g[yy][xx]==col:
                        seen.add((yy,xx)); q.append((yy,xx))
            y0=min(y for y,x in pts); y1=max(y for y,x in pts)
            x0=min(x for y,x in pts); x1=max(x for y,x in pts)
            if all(g[y0][x]==col and g[y1][x]==col for x in range(x0,x1+1)) and all(g[y][x0]==col and g[y][x1]==col for y in range(y0,y1+1)):
